 <section id="selection" class="screen selector"><div class="selectbox"><div class="selecthead"><h2>Choose your fighter</h2><p>12 FIGHTERS &nbsp;·&nbsp; 6 AVAILABLE</p></div><div id="roster" class="roster"></div><aside class="profile"><div class="bigportrait" id="bigPortrait"></div><h3 id="charName">Mara Voss</h3><div class="subtitle" id="charSub">THE STREET PHANTOM</div><p class="bio" id="charBio"></p><div class="stats" id="stats"></div><div class="costume"><button id="prevCost">←</button><div class="costumename"><small>OUTFIT</small><strong id="costName">Night Shift</strong></div><button id="nextCost">→</button></div></aside><div class="selectfoot"><span id="unlockHint">✦ &nbsp;6 FIGHTERS LOCKED · CLEAR DISTRICTS TO EARN THEM</span><button class="primary" id="fightBtn">Take the streets&nbsp; ↗</button></div></div></section>
 <div class="gamehud" id="hud"><div class="hudtop"><div class="healthbox"><div class="hudname" id="hudName">MARA VOSS</div><div class="healthline"><div class="healthfill" id="health"></div></div></div><div class="hints"><span class="desktophelp">MOVE WASD / ARROWS &nbsp;·&nbsp; ATTACK J &nbsp;·&nbsp; SPECIAL K &nbsp;·&nbsp; DODGE SPACE</span><button id="pauseBtn">Ⅱ &nbsp; PAUSE</button></div></div><div class="stageinfo"><strong id="stageName">THE OLD QUARTER</strong><span id="stageCount">DISTRICT 01 — 09</span></div><div id="bossbar" class="bossbar">NIGHT THRALL <i></i></div><div class="bottomhud"><div class="objective" id="objective">CLEAR THE STREET · 0 / 5</div><div class="specialmeter">BLOOD RUSH<div class="specialbar"><i id="specialFill"></i></div></div></div><div class="mobilecontrols"><div class="dpad"><button class="touchbtn up" data-key="up">↑</button><button class="touchbtn left" data-key="left">←</button><button class="touchbtn down" data-key="down">↓</button><button class="touchbtn right" data-key="right">→</button></div><div class="combatbtns"><button class="touchbtn special" data-key="special">K</button><button class="touchbtn attack" data-key="attack">J</button></div></div></div>
 <div class="toast" id="toast"></div><div class="overlay" id="overlay"><div class="dialog"><div class="eyebrow" id="dialogEyebrow">DISTRICT CLEARED</div><h2 id="dialogTitle">The night<br>recedes.</h2><p id="dialogText">The city remembers your name.</p><div class="actions" id="dialogActions"></div></div></div></main>
 <script>
+const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d');let W=innerWidth,H=innerHeight,DPR=1;function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
+const fighters=[
+['Mara Voss','The Street Phantom','A courier who learned to fight in the alleys and never stopped moving.','STRIKER','#ed5369','Night Shift'],['Dante Reyes','Iron Fist','A former prizefighter. One clean hit is all he needs.','BRAWLER','#e7a24b','Corner King'],['Juno Park','Neon Blade','A rooftop runner with a razor-sharp sense of timing.','DUELIST','#55d5d5','After Hours'],['Calder Knox','The Wall','A nightclub bouncer who can take as much as he gives.','TANK','#9f8bea','Last Call'],['Ivy Chen','Ghostwire','A tech thief who turns the city itself into a weapon.','TRICKSTER','#8bd67c','Glitch'],['Rook','The Hound','A quiet hunter with a mean right hook and no patience.','HUNTER','#d6bd91','Bloodhound'],['Silas Vale','The Vampire','Centuries old. Finally fighting on the right side.','VAMPIRE','#c8589d','Crimson Noble'],['Tess Wilder','Wildfire','A street medic whose kickboxing burns twice as hot.','KICKBOXER','#ff775c','Hot Zone'],['Bishop','Heavy Weather','A towering ex-wrestler who makes the pavement shake.','GRAPPLER','#93a4c7','Concrete'],['Nadia Sayegh','Silver Tongue','A sharp-eyed detective, quicker with her baton than her badge.','COUNTER','#e8d47d','Plain Clothes'],['Echo','Sound & Fury','A club DJ who drops the beat—and anyone in range.','RHYTHM','#c084f2','Feedback'],['Ash Okafor','Last Light','A martial arts teacher who refuses to let darkness win.','MARTIAL ARTIST','#73c9a1','Dawn Guard']];
+const costumes=['Night Shift','Streetwear','Blood Moon','Afterglow','Midnight'];const stages=['The Old Quarter','Neon Mile','The Red Line','Saint Mercy Hospital','The Drowned Market','Blackglass Tower','The Ashen Docks','The Velvet Cathedral','The Last Dawn'];let unlocked=JSON.parse(localStorage.getItem('bloodlineUnlocks')||'[0,1,2,3,4,5]');let chosen=0,costIdx=0,mode='menu',stage=0,player,enemies=[],particles=[],keys={},camera=0,worldW=2400,kills=0,spawned=0,spawnTotal=5,special=0,shake=0,tick=0,attackCd=0,specialCd=0,invuln=0,paused=false;
+function svgFighter(i,large=false){let f=fighters[i],c=f[4],w=large?150:85,h=large?180:105;return `<svg viewBox="0 0 100 120" width="${w}" height="${h}" xmlns="http://www.w3.org/2000/svg"><ellipse cx="50" cy="113" rx="25" ry="5" fill="#090711" opacity=".55"/><path d="M38 43 Q22 39 20 61 L15 92 Q26 101 38 90 L43 66 M61 44 Q78 41 80 61 L87 84 Q78 94 69 83 L60 65" fill="${c}" stroke="#211827" stroke-width="3"/><path d="M34 46 Q50 37 66 46 L72 88 Q51 98 29 88Z" fill="#25202d" stroke="#111" stroke-width="2"/><path d="M35 85 L30 108 L46 109 L51 91 M56 91 L60 109 L76 108 L66 84" fill="#17131d" stroke="#08070c" stroke-width="3"/><path d="M38 31 Q36 12 51 12 Q67 12 65 34 L61 47 L40 45Z" fill="#e6bca7" stroke="#241923" stroke-width="2"/><path d="M36 29 Q36 8 53 9 Q67 12 67 28 L61 23 Q49 30 37 25Z" fill="#211622"/><path d="M43 32h5m8 0h5" stroke="#311a22" stroke-width="2"/><path d="M46 39q5 3 10 0" fill="none" stroke="#9b3d4d" stroke-width="2"/><path d="M36 47 Q50 52 66 47 L68 55 Q51 61 34 55Z" fill="${c}"/><path d="M33 53 L23 72 M67 54 L79 67" stroke="${c}" stroke-width="6" stroke-linecap="round"/><circle cx="49" cy="32" r="1.7" fill="${c}"/><circle cx="60" cy="32" r="1.7" fill="${c}"/></svg>`}
+const roster=document.querySelector('#roster');function drawRoster(){roster.innerHTML=fighters.map((f,i)=>`<button class="fighter ${unlocked.includes(i)?'':'locked'} ${i===chosen?'selected':''}" data-i="${i}"><span class="num">${String(i+1).padStart(2,'0')}</span>${!unlocked.includes(i)?'<span class="locktag">🔒</span>':''}<span class="name">${f[0]}</span><span class="style">${f[3]}</span><span class="portrait">${svgFighter(i)}</span></button>`).join('');roster.querySelectorAll('.fighter').forEach(el=>el.onclick=()=>{let i=+el.dataset.i;if(!unlocked.includes(i)){toastMsg('FIGHTER LOCKED',`Clear district ${Math.max(1,Math.floor((i-6)/1)+1)} to unlock ${fighters[i][0]}.`);return}chosen=i;costIdx=0;updateProfile();drawRoster()})}
+function updateProfile(){let f=fighters[chosen];document.querySelector('#bigPortrait').innerHTML=svgFighter(chosen,true);document.querySelector('#charName').textContent=f[0];document.querySelector('#charSub').textContent=f[1].toUpperCase();document.querySelector('#charBio').textContent=f[2];document.querySelector('#costName').textContent=costumes[costIdx];document.querySelector('#stats').innerHTML=['POWER','SPEED','RANGE'].map((s,j)=>`<div class="stat">${s}<div class="meter"><i style="width:${[58,79,64][j]+((chosen+j)%3)*9}%;background:${f[4]}"></i></div></div>`).join('');document.querySelector('#hudName').textContent=f[0].toUpperCase()}
+drawRoster();updateProfile();document.querySelector('#prevCost').onclick=()=>{costIdx=(costIdx+4)%5;updateProfile()};document.querySelector('#nextCost').onclick=()=>{costIdx=(costIdx+1)%5;updateProfile()};
+function show(id){document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));document.querySelector('#'+id).classList.add('active')}
+function toastMsg(title,sub){let t=document.querySelector('#toast');t.innerHTML=title+(sub?`<small>${sub}</small>`:'');t.classList.add('show');clearTimeout(toastMsg.timer);toastMsg.timer=setTimeout(()=>t.classList.remove('show'),2100)}
+function skyline(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#17152a');g.addColorStop(.52,'#3b253d');g.addColorStop(1,'#a04a53');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);let horizon=H*.65;ctx.fillStyle='#211a31';for(let i=0;i<20;i++){let x=((i*170-camera*.18)%(W+200)+W+200)%(W+200)-80,bh=100+(i*71%190);ctx.fillRect(x,horizon-bh,115,bh);ctx.fillStyle='#35263b';ctx.fillRect(x+8,horizon-bh+10,99,3);for(let y=horizon-bh+25;y<horizon-10;y+=24)for(let xx=x+13;xx<x+108;xx+=25){ctx.fillStyle=(i+Math.floor(y)+Math.floor(xx))%3?'#e57c6680':'#eecb7560';ctx.fillRect(xx,y,7,10)}ctx.fillStyle='#211a31';if(i%4===0){ctx.fillStyle='#e8485e';ctx.fillRect(x+46,horizon-bh-18,24,16);ctx.fillStyle='#ffd49a';ctx.font='bold 8px monospace';ctx.fillText('OPEN',x+47,horizon-bh-7);ctx.fillStyle='#211a31'}}ctx.fillStyle='#241b2a';ctx.fillRect(0,horizon,W,H-horizon);ctx.fillStyle='#362532';ctx.fillRect(0,horizon,W,8);ctx.fillStyle='#17131e';ctx.fillRect(0,H*.86,W,H*.14);ctx.strokeStyle='#75606a';ctx.globalAlpha=.4;ctx.lineWidth=2;for(let x=-(camera%125);x<W;x+=125){ctx.beginPath();ctx.moveTo(x,H*.65);ctx.lineTo(x-40,H);ctx.stroke()}ctx.globalAlpha=1;for(let x=-(camera%330);x<W;x+=330){ctx.fillStyle='#15121a';ctx.fillRect(x+30,H*.55,4,H*.16);ctx.fillStyle='#ffcb6a';ctx.fillRect(x+24,H*.55,16,5)}
+}
+function drawPerson(x,y,color,scale=1,foe=false,frame=0){ctx.save();ctx.translate(x-camera,y);ctx.scale(scale,scale);ctx.fillStyle='#09071166';ctx.beginPath();ctx.ellipse(0,2,22,6,0,0,Math.PI*2);ctx.fill();let bob=Math.sin(frame*.17)*1.5;ctx.translate(0,bob);ctx.fillStyle=foe?'#311d2b':'#211827';ctx.fillRect(-13,-43,26,34);ctx.fillStyle=color;ctx.fillRect(-15,-45,30,9);ctx.fillStyle=foe?'#d1a895':'#e5bba4';ctx.beginPath();ctx.arc(0,-54,10,0,Math.PI*2);ctx.fill();ctx.fillStyle=foe?'#261321':'#241821';ctx.fillRect(-10,-61,20,7);ctx.fillStyle=color;ctx.fillRect(-17,-41,8,24);ctx.fillRect(9,-41,8,24);ctx.fillStyle='#17131b';ctx.fillRect(-11,-10,9,13);ctx.fillRect(3,-10,9,13);if(foe){ctx.fillStyle='#fa435e';ctx.fillRect(-5,-56,3,2);ctx.fillRect(3,-56,3,2)}else{ctx.fillStyle='#f0d7b8';ctx.fillRect(-5,-56,3,2);ctx.fillRect(3,-56,3,2)}ctx.restore()}

input.newString:
ctx.restore()}
function draw(){tick++;ctx.clearRect(0,0,W,H);skyline();if(mode==='menu'){let cx=W*.73,cy=H*.75;drawPerson(cx,cy,fighters[6][4],2.2,true,tick);drawPerson(cx-100,cy+35,fighters[0][4],1.9,false,tick);drawPerson(cx+105,cy+22,fighters[2][4],1.8,false,tick);ctx.fillStyle='#fa4c5d';ctx.globalAlpha=.12;ctx.beginPath();ctx.arc(cx,cy-65,160,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}else if(mode==='select'){let cx=W*.76,cy=H*.84;drawPerson(cx,cy,fighters[6][4],2,true,tick);drawPerson(cx-110,cy+25,fighters[0][4],1.7,false,tick)}else if(mode==='play'){if(shake>0)shake*=.85;ctx.save();if(shake>1)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);for(let p of particles){ctx.globalAlpha=Math.max(0,p.life/24);ctx.fillStyle=p.color;ctx.fillRect(p.x-camera,p.y,p.size,p.size);p.x+=p.vx;p.y+=p.vy;p.life--}ctx.globalAlpha=1;particles=particles.filter(p=>p.life>0);if(player){drawPerson(player.x,player.y,fighters[chosen][4],1.15,false,tick);if(player.flash){ctx.globalAlpha=.55;ctx.fillStyle='#fff';ctx.fillRect(player.x-camera-17,player.y-60,34,58);ctx.globalAlpha=1;player.flash--}if(player.dodge>0){ctx.globalAlpha=.3;ctx.fillStyle=fighters[chosen][4];ctx.beginPath();ctx.ellipse(player.x-camera-15,player.y-32,26,34,0,0,7);ctx.fill();ctx.globalAlpha=1;player.dodge--}}
for(let e of enemies){drawPerson(e.x,e.y,e.boss?'#9b3655':'#726079',e.boss?1.55:1,e.boss,tick);if(e.hit){ctx.globalAlpha=.5;ctx.fillStyle='#fff';ctx.fillRect(e.x-camera-18,e.y-60,36,55);ctx.globalAlpha=1;e.hit--}ctx.fillStyle='#130d16';ctx.fillRect(e.x-camera-17,e.y-70,e.boss?45:34,4);ctx.fillStyle=e.boss?'#fa4c5d':'#d97477';ctx.fillRect(e.x-camera-17,e.y-70,(e.boss?45:34)*Math.max(0,e.hp/e.max),4)}ctx.restore();if(player){camera=Math.max(0,Math.min(worldW-W,player.x-W*.36));document.querySelector('#health').style.width=Math.max(0,player.hp)+'%';document.querySelector('#specialFill').style.width=special+'%';document.querySelector('#objective').textContent=stage===8&&spawned>=spawnTotal?'DEFEAT THE NIGHT KING':`CLEAR THE STREET · ${kills} / ${spawnTotal}`;let boss=enemies.find(e=>e.boss);document.querySelector('#bossbar').classList.toggle('show',!!boss);if(boss)document.querySelector('#bossbar i').style.width=`${Math.max(0,boss.hp/boss.max*100)}%`}}
requestAnimationFrame(draw)}requestAnimationFrame(draw);
function startGame(){mode='play';show('landing');document.querySelector('#landing').classList.remove('active');document.querySelector('#selection').classList.remove('active');document.querySelector('#hud').classList.add('show');stage=0;beginStage()}
function beginStage(){worldW=Math.max(2200,W*2.7);camera=0;kills=0;spawned=0;spawnTotal=stage===8?1:5+Math.floor(stage/2);enemies=[];player={x:100,y:H*.81,hp:100,dodge:0,flash:0};paused=false;document.querySelector('#stageName').textContent=stages[stage].toUpperCase();document.querySelector('#stageCount').textContent=`DISTRICT ${String(stage+1).padStart(2,'0')} — 09`;document.querySelector('#health').style.width='100%';document.querySelector('#bossbar').classList.remove('show');setTimeout(spawnEnemy,900);if(stage===8)toastMsg('THE LAST DAWN','The blood king waits at the cathedral.')}
function spawnEnemy(){if(mode!=='play'||paused||spawned>=spawnTotal)return;let boss=stage===8;spawned++;enemies.push({x:Math.min(worldW-120,player.x+Math.min(W*.75,560)+Math.random()*180),y:H*.81+(Math.random()-.5)*H*.09,hp:boss?300:stage*9+55,max:boss?300:stage*9+55,boss,hit:0,cd:0});if(spawned<spawnTotal)setTimeout(spawnEnemy,1100+Math.random()*650)}
function burst(x,y,color,n=9){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*8,vy:(Math.random()-.6)*7,life:12+Math.random()*15,size:2+Math.random()*4,color})}
function attack(){if(mode!=='play'||paused||attackCd>0)return;attackCd=19;player.flash=7;let range=chosen===2||chosen===6?105:78;let hit=false;for(let e of enemies){if(Math.abs(e.x-player.x)<range&&Math.abs(e.y-player.y)<55){e.hp-=chosen===1||chosen===8?32:22;e.hit=7;e.x+=player.x<e.x?12:-12;burst(e.x-camera,e.y-45,fighters[chosen][4],7);hit=true;if(e.hp<=0){kills++;special=Math.min(100,special+13);burst(e.x-camera,e.y-45,'#fa4c5d',15)}}}enemies=enemies.filter(e=>e.hp>0);if(hit&&chosen===10)special=Math.min(100,special+5);attackCd=chosen===0?13:19;checkStage()}
function useSpecial(){if(mode!=='play'||paused||special<45||specialCd>0)return;special-=45;specialCd=45;shake=12;toastMsg('BLOOD RUSH','The street belongs to you.');for(let e of enemies){if(Math.abs(e.x-player.x)<260){e.hp-=chosen===6?130:85;e.hit=14;burst(e.x-camera,e.y-42,fighters[chosen][4],20)}}enemies=enemies.filter(e=>{if(e.hp<=0){kills++;return false}return true});checkStage()}
function checkStage(){if(kills>=spawnTotal&&enemies.length===0){if(stage===8){finishGame(true);return}document.querySelector('#hud').classList.remove('show');document.querySelector('#dialogEyebrow').textContent='DISTRICT '+String(stage+1).padStart(2,'0')+' CLEARED';document.querySelector('#dialogTitle').innerHTML='One step<br>closer.';let unlock=stage<6?6+stage:null;if(unlock!==null&&!unlocked.includes(unlock)){unlocked.push(unlock);localStorage.setItem('bloodlineUnlocks',JSON.stringify(unlocked));document.querySelector('#dialogText').textContent=`${fighters[unlock][0]} joins the fight. The city owes you one.`}else document.querySelector('#dialogText').textContent='The night retreats. But the city is still not safe.';document.querySelector('#dialogActions').innerHTML='<button class="primary" id="nextBtn">Next district ↗</button>';document.querySelector('#overlay').classList.add('show');document.querySelector('#nextBtn').onclick=()=>{document.querySelector('#overlay').classList.remove('show');stage++;beginStage();document.querySelector('#hud').classList.add('show')}}}
function finishGame(win){mode='menu';document.querySelector('#hud').classList.remove('show');document.querySelector('#dialogEyebrow').textContent='THE CITY REMEMBERS';document.querySelector('#dialogTitle').innerHTML='Daybreak.';document.querySelector('#dialogText').textContent='Nine districts. One last night. You saved the city—but the bloodline never truly ends.';document.querySelector('#dialogActions').innerHTML='<button class="primary" id="againBtn">Fight again ↗</button><button class="text-button" id="menuBtn">Main menu</button>';document.querySelector('#overlay').classList.add('show');document.querySelector('#againBtn').onclick=()=>{document.querySelector('#overlay').classList.remove('show');show('selection');mode='select';drawRoster();updateProfile()};document.querySelector('#menuBtn').onclick=()=>{document.querySelector('#overlay').classList.remove('show');show('landing')}}

