function updateGame(){if(mode!=='play'||paused||!player)return;if(attackCd>0)attackCd--;if(specialCd>0)specialCd--;if(invuln>0)invuln--;let speed=3.35;let dx=(keys.right?1:0)-(keys.left?1:0),dy=(keys.down?1:0)-(keys.up?1:0);player.x=Math.max(24,Math.min(worldW-35,player.x+dx*speed));player.y=Math.max(H*.69,Math.min(H*.91,player.y+dy*speed*.55));if(keys.attack)attack();if(keys.special)useSpecial();for(let e of enemies){e.cd=Math.max(0,e.cd-1);let vx=player.x-e.x,vy=player.y-e.y;if(Math.abs(vx)>46)e.x+=Math.sign(vx)*(e.boss?1.15:1.55);if(Math.abs(vy)>15)e.y+=Math.sign(vy)*.8;if(Math.abs(vx)<48&&Math.abs(vy)<24&&e.cd===0&&invuln===0){e.cd=e.boss?28:40;player.hp-=e.boss?12:8;invuln=26;shake=5;burst(player.x-camera,player.y-40,'#fa4c5d',5);if(player.hp<=0){player.hp=0;finishFail()}}}if(player.x>worldW-230&&spawned===spawnTotal&&enemies.length===0)checkStage()}
setInterval(updateGame,1000/60);
function finishFail(){mode='menu';document.querySelector('#hud').classList.remove('show');document.querySelector('#dialogEyebrow').textContent='THE NIGHT TAKES ITS DUE';document.querySelector('#dialogTitle').innerHTML='Not this<br>time.';document.querySelector('#dialogText').textContent='The streets are still out there. Get back up and try again.';document.querySelector('#dialogActions').innerHTML='<button class="primary" id="retryBtn">Try again ↗</button><button class="text-button" id="menuFailBtn">Change fighter</button>';document.querySelector('#overlay').classList.add('show');document.querySelector('#retryBtn').onclick=()=>{document.querySelector('#overlay').classList.remove('show');mode='play';document.querySelector('#hud').classList.add('show');beginStage()};document.querySelector('#menuFailBtn').onclick=()=>{document.querySelector('#overlay').classList.remove('show');mode='select';show('selection');drawRoster();updateProfile()}}
document.querySelector('#playBtn').onclick=()=>{mode='select';show('selection');drawRoster();updateProfile()};document.querySelector('#fightBtn').onclick=startGame;document.querySelector('#controlsBtn').onclick=()=>{document.querySelector('#dialogEyebrow').textContent='CONTROLS';document.querySelector('#dialogTitle').innerHTML='Own the<br>night.';document.querySelector('#dialogText').innerHTML='Move: <b>WASD</b> or <b>arrow keys</b><br>Attack: <b>J</b> &nbsp;·&nbsp; Special: <b>K</b><br>Dodge: <b>Space</b> &nbsp;·&nbsp; Pause: <b>Esc</b><br><br>On mobile, use the touch controls.';document.querySelector('#dialogActions').innerHTML='<button class="primary" id="closeHow">Got it</button>';document.querySelector('#overlay').classList.add('show');document.querySelector('#closeHow').onclick=()=>document.querySelector('#overlay').classList.remove('show')};document.querySelector('#pauseBtn').onclick=()=>{if(mode!=='play')return;paused=!paused;if(paused){document.querySelector('#dialogEyebrow').textContent='TAKE A BREATH';document.querySelector('#dialogTitle').textContent='Paused';document.querySelector('#dialogText').textContent='The city can wait a moment.';document.querySelector('#dialogActions').innerHTML='<button class="primary" id="resumeBtn">Back to it ↗</button><button class="text-button" id="quitBtn">Quit to menu</button>';document.querySelector('#overlay').classList.add('show');document.querySelector('#resumeBtn').onclick=()=>{paused=false;document.querySelector('#overlay').classList.remove('show')};document.querySelector('#quitBtn').onclick=()=>{paused=false;mode='menu';document.querySelector('#overlay').classList.remove('show');document.querySelector('#hud').classList.remove('show');show('landing')}}};
function keydown(e){let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='escape'&&mode==='play')document.querySelector('#pauseBtn').click();if(k==='enter'&&mode==='menu'){mode='select';show('selection')}if(['w','arrowup'].includes(k))keys.up=true;if(['s','arrowdown'].includes(k))keys.down=true;if(['a','arrowleft'].includes(k))keys.left=true;if(['d','arrowright'].includes(k))keys.right=true;if(k==='j')keys.attack=true;if(k==='k')keys.special=true;if(k===' '&&player&&mode==='play'&&player.dodge<=0){player.dodge=18;invuln=22;player.x=Math.min(worldW-30,player.x+(keys.left?-120:120));burst(player.x-camera,player.y-35,fighters[chosen][4],7)}}function keyup(e){let k=e.key.toLowerCase();if(['w','arrowup'].includes(k))keys.up=false;if(['s','arrowdown'].includes(k))keys.down=false;if(['a','arrowleft'].includes(k))keys.left=false;if(['d','arrowright'].includes(k))keys.right=false;if(k==='j')keys.attack=false;if(k==='k')keys.special=false}addEventListener('keydown',keydown);addEventListener('keyup',keyup);document.querySelectorAll('.touchbtn').forEach(b=>{let k=b.dataset.key,down=e=>{e.preventDefault();keys[k]=true},up=e=>{e.preventDefault();keys[k]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointerleave',up);b.addEventListener('pointercancel',up)});
</script></body></html>

